// function mergeObjects(obj1, obj2) mein dono objects do
// Agar koi bhi object nahi: {}
// Dono ka spread merge karo

solution:
function mergeObjects(obj1, obj2) {
  if (typeof obj1 !== "object" || obj1 === null) return {}
  if (typeof obj2 !== "object" || obj2 === null) return {}
  return { ...obj1, ...obj2 }
}
